export function calculateBatTrachGua(birthYear, gender = 'male') {
  const y = parseInt(birthYear, 10) || 1990;
  let sum = String(y).split('').reduce((a, b) => a + parseInt(b, 10), 0);
  while (sum >= 10) {
    sum = String(sum).split('').reduce((a, b) => a + parseInt(b, 10), 0);
  }
  let gua;
  if (gender === 'male') {
    gua = y < 2000 ? 11 - sum : 10 - sum;
  } else {
    gua = y < 2000 ? sum + 4 : sum + 5;
  }
  while (gua > 9) gua -= 9;
  if (gua <= 0) gua += 9;
  if (gua === 5) gua = gender === 'male' ? 2 : 8;
  return { guaNumber: gua, ...BAT_TRACH_GUA[gua] };
}
